package asia.aaii.greenbanana.preview;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.media.AudioManager;import android.view.*;import android.widget.*;import android.view.animation.OvershootInterpolator;
public class MainActivity extends Activity {
final int GREEN=Color.rgb(13,86,52),GOLD=Color.rgb(235,190,55),BG=Color.rgb(244,248,240);LinearLayout root,body;int page=0;boolean sound=true,animate=true;
String[] titles={"Welcome","Login","Dashboard","3D Master Plan","Plantation","Facilities","Factory Exterior","Factory Interior","Production Process","Showroom","Training","Reports"};
String[] desc={"GREEN BANANA MYANMAR • 100 ACRE MASTER PLAN","Offline secure demonstration access","Your sustainable development project","Interactive master plan placeholder • Full 3D requires original asset package","60 acres • Plantation Blocks A to F","Explore 10 development zones","Banana processing facility • 8 acres","Factory interior production zones","Fibre extraction → Drying → Weaving → Products","Sustainable banana fibre products","Offline learning modules • Full 38-page PDF requires full package","Illustrative demo data only"};
@Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(GREEN);getWindow().setNavigationBarColor(GREEN);android.content.SharedPreferences p=getSharedPreferences("feedback",0);sound=p.getBoolean("sound",true);animate=p.getBoolean("animation",true);show(0);}
GradientDrawable bg(int c,int r){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(r);return d;}
TextView text(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextColor(color);t.setTextSize(size);t.setPadding(18,14,18,14);if(bold)t.setTypeface(null,Typeface.BOLD);return t;}
void add(LinearLayout l,View v){l.addView(v,new LinearLayout.LayoutParams(-1,-2));}
void click(View v,Runnable r){v.setClickable(true);v.setOnTouchListener((view,e)->{if(!animate)return false;if(e.getAction()==0)view.animate().scaleX(.95f).scaleY(.95f).setDuration(75).start();else if(e.getAction()==1||e.getAction()==3)view.animate().scaleX(1).scaleY(1).setDuration(210).setInterpolator(new OvershootInterpolator()).start();return false;});v.setOnClickListener(view->{view.performHapticFeedback(1);if(sound)((AudioManager)getSystemService(AUDIO_SERVICE)).playSoundEffect(0,.7f);r.run();});}
void button(LinearLayout target,String label,int color,Runnable callback){TextView t=text(label,16,color==GREEN?Color.WHITE:GREEN,true);t.setGravity(Gravity.CENTER);t.setBackground(bg(color,23));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,7,0,7);target.addView(t,lp);click(t,callback);}
void section(String label){add(body,text(label,20,GREEN,true));}
void card(String title,String details,int to){LinearLayout c=new LinearLayout(this);c.setOrientation(1);c.setPadding(14,8,14,9);c.setBackground(bg(Color.WHITE,22));add(c,text(title,17,GREEN,true));add(c,text(details,13,Color.DKGRAY,false));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,6,0,8);body.addView(c,lp);click(c,()->show(to));}
void show(int p){page=p;root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(BG);setContentView(root);TextView header=text("🍃  GREEN BANANA MYANMAR    •    OFFLINE",16,Color.WHITE,true);header.setBackgroundColor(GREEN);add(root,header);
ScrollView sc=new ScrollView(this);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));body=new LinearLayout(this);body.setOrientation(1);body.setPadding(20,18,20,12);sc.addView(body);section(titles[p]);add(body,text(desc[p],15,Color.DKGRAY,false));
if(p==0){TextView hero=text("🌿\n100 ACRES\nSUSTAINABLE INNOVATION",29,GREEN,true);hero.setGravity(Gravity.CENTER);hero.setPadding(10,40,10,40);hero.setBackground(bg(Color.rgb(222,240,219),28));add(body,hero);button(body,"GET STARTED",GREEN,()->show(1));}
if(p==1){EditText pin=new EditText(this);pin.setHint("Enter demonstration PIN");pin.setInputType(18);pin.setSingleLine(true);add(body,pin);button(body,"UNLOCK OFFLINE DEMO",GREEN,()->{if(pin.getText().toString().equals("252566954"))show(2);else Toast.makeText(this,"Demo PIN is 252566954",Toast.LENGTH_SHORT).show();});}
if(p==2){String[] names={"3D MASTER PLAN","PLANTATION","FACILITIES","FACTORY TOUR","PRODUCTION PROCESS","PRODUCT SHOWROOM","TRAINING","REPORTS"};int[] routes={3,4,5,6,8,9,10,11};for(int i=0;i<names.length;i++)card(names[i],"Tap to explore offline",routes[i]);button(body,"TOUCH FEEDBACK SETTINGS",GOLD,()->settings());}
if(p==3){TextView v=text("🗺️\n\nOFFLINE MASTER PLAN\n\n10 Zones • 100 Acres\n\nFull GLB viewing available in the original full-source package.",22,GREEN,true);v.setGravity(Gravity.CENTER);v.setBackground(bg(Color.rgb(220,239,216),22));v.setPadding(10,45,10,45);add(body,v);button(body,"TOP VIEW",GOLD,()->Toast.makeText(this,"Preview top view",0).show());button(body,"ZONE LIST",GREEN,()->show(5));}
if(p==4){for(int i=0;i<6;i++)card("PLANTATION BLOCK "+(char)('A'+i),"Banana growing zone • illustrative layout",3);}
if(p==5){String[] z={"Plantation • 60 acres","Nursery • 5 acres","Reservoir & Irrigation • 4 acres","Processing Factory • 8 acres","Warehouse • 4 acres","Admin & Training • 4 acres","Staff/Canteen/Clinic • 5 acres","Solar Utilities • 4 acres","Machinery • 3 acres","Waste Treatment • 3 acres"};for(int i=0;i<z.length;i++)card(z[i],"Project facility details",i==3?6:3);}
if(p==6){card("Factory exterior","Production building overview",7);card("Interior walkthrough","View conceptual factory interiors",7);}
if(p==7){card("Fibre production hall","Work area • conceptual",8);card("Drying, Storage & Packing","Work areas • conceptual",8);}
if(p==8){String[] steps={"1. Banana Harvest","2. Stem Collection","3. Fibre Extraction","4. Washing & Drying","5. Weaving / Processing","6. Product Packaging"};for(String s:steps)card(s,"Production demo process",9);}
if(p==9){for(String s:new String[]{"Eco Textiles","Banana Fibre Bags","Reusable Products","Banana Fibre Paper"})card(s,"Sustainable fibre product showcase",10);}
if(p==10){card("Training Guide","Full 38-page PDF is not bundled in this preview",2);card("Plantation Operations","Overview of practical farming lessons",4);}
if(p==11){String[] a={"Plantation 60 acres","Processing 8 acres","Solar 4 acres","Utilities 4 acres","Production dashboard — demo values"};for(String s:a)card(s,"Illustrative metrics; not actual production",2);}
LinearLayout nav=new LinearLayout(this);nav.setBackgroundColor(GREEN);root.addView(nav);String[] n={"Home","Zones","3D","Products","Reports"};int[] dest={2,5,3,9,11};for(int i=0;i<5;i++){final int d=dest[i];TextView t=text(n[i],12,Color.WHITE,true);t.setGravity(Gravity.CENTER);nav.addView(t,new LinearLayout.LayoutParams(0,60,1));click(t,()->show(d));}}
void settings(){String[] items={"Click Sound: "+(sound?"ON":"OFF"),"Pop Animation: "+(animate?"ON":"OFF")};new AlertDialog.Builder(this).setTitle("Touch Feedback Settings").setItems(items,(d,which)->{if(which==0)sound=!sound;else animate=!animate;getSharedPreferences("feedback",0).edit().putBoolean("sound",sound).putBoolean("animation",animate).apply();settings();}).setPositiveButton("Done",(d,w)->{}).show();}
@Override public void onBackPressed(){if(page==2||page==0)super.onBackPressed();else show(2);}
}